	local d = T.driver(w, T.TESTCHAR)
	T.settle(w)
	w:addBot(T.BOB)
	w:addBot(T.ANITA)
	w:group({ T.TESTCHAR, T.BOB, T.ANITA })
	T.settle(w)
	ok(d.W.Drive.SetMode("raid"), "raid mode")
	ok(d.W.Drive.SetOpen(true), "raid summons on")
	T.openDrive(d)
	w:advance(1)
	d:clickText("Not here (2)")
	w:advance(1)
	local texts = d:visibleTexts()
	local ai, bi
	for i, s in ipairs(texts) do
		if not ai and string.find(s, "Anita", 1, true) then ai = i end
		if not bi and string.find(s, "Bob", 1, true) then bi = i end
	end
	ok(ai and bi and ai < bi, "Anita is listed before Bob")
	T.clean(w)
end)

