test("breakit Drive.Raid: turning a picked summoner off clears them from the saved summoner list", function()
    local w = T.newWorld()
    local d = T.driver(w, T.ANITA, { spot = "Orgrimmar" })
    T.settle(w)
    local ch = d.W.Char()
    ch.captain = ""
    ch.summoners = {}
    ch.crew = {}
    ok(d.W.Drive.RaidPick(T.BOB, true), "Bob is picked as a summoner")
    eq(#ch.summoners, 1, "the picked summoner is saved in the summoner list")
    d.W.Drive.RaidPick(T.BOB, false)
    eq(#ch.summoners, 0, "turning the pick off leaves no summoner behind")
    T.clean(w)
end)

